import pandas as pd
from difflib import SequenceMatcher

vendors_df = pd.read_excel('/root/vendors.xlsx')
vendor_names = [row['name'].strip() for _, row in vendors_df.iterrows()]
vendor_lookup = {}
for _, row in vendors_df.iterrows():
    vendor_lookup[row['name'].strip()] = {'id': row['id'].strip(), 'iban': row['iban'].strip()}

po_df = pd.read_csv('/root/purchase_orders.csv')
po_lookup = {}
for _, row in po_df.iterrows():
    po_lookup[row['po_number'].strip()] = {'vendor_id': row['vendor_id'].strip(), 'amount': float(row['amount'])}

# Check the 3 special invoices
test_cases = [
    {'page': 51, 'vendor': 'Safe Vendor Ltd', 'amount': 1000.00, 'iban': 'IBANSAFE001', 'po': 'PO-9001'},
    {'page': 52, 'vendor': 'Fuzzy Match Systems Inc.', 'amount': 2000.00, 'iban': 'IBANFUZZ002', 'po': 'PO-9002'},
    {'page': 53, 'vendor': 'Boundary Corp', 'amount': 500.01, 'iban': 'IBANBOUND003', 'po': 'PO-9003'},
]

for tc in test_cases:
    print(f"\n--- Page {tc['page']}: {tc['vendor']} ---")
    # Find best match
    best_match = None
    best_score = 0
    for vn in vendor_names:
        score = SequenceMatcher(None, tc['vendor'].lower(), vn.lower()).ratio()
        if score > best_score:
            best_score = score
            best_match = vn
    print(f"  Best vendor match: '{best_match}' (score: {best_score:.3f})")

    if best_match and best_score >= 0.75:
        vi = vendor_lookup[best_match]
        print(f"  Vendor ID: {vi['id']}, IBAN: {vi['iban']}")
        print(f"  IBAN match: {tc['iban'] == vi['iban']}")

        if tc['po'] in po_lookup:
            poi = po_lookup[tc['po']]
            print(f"  PO found: vendor_id={poi['vendor_id']}, amount={poi['amount']}")
            print(f"  Amount diff: {abs(tc['amount'] - poi['amount']):.4f}")
            print(f"  Vendor ID match: {poi['vendor_id'] == vi['id']}")
        else:
            print(f"  PO '{tc['po']}' NOT found in purchase_orders.csv")
PYEOF
